                ),
            )
        )
    except ValueError:
        logger.warning("Ignoring invalid DEPOS_OLLAMA_SUBSEQUENT_TIMEOUT / DEPOS_LLM_OLLAMA_SUBSEQUENT_TIMEOUT")
    try:
